-- CAN DBC 增量解析服务建表脚本（H2 MODE=MySQL；数据仅保留在 JVM 生命周期内）

-- DBC 导入幂等请求记录：requestId 唯一；content_hash 为规范化定义哈希，用于同参/异参重放判定
CREATE TABLE IF NOT EXISTS dbc_import_requests (
    request_id    VARCHAR(128) NOT NULL,
    version       VARCHAR(128) NOT NULL,
    content_hash  VARCHAR(128) NOT NULL,
    outcome       VARCHAR(32)  NOT NULL,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_dbc_import_requests PRIMARY KEY (request_id)
);
COMMENT ON COLUMN dbc_import_requests.request_id IS '导入请求幂等键，同键重放不重复写入';
COMMENT ON COLUMN dbc_import_requests.version IS '本次导入的 DBC 版本名';
COMMENT ON COLUMN dbc_import_requests.content_hash IS '规范化定义内容 SHA-256（不含 requestId），异参重放据此判定';
COMMENT ON COLUMN dbc_import_requests.outcome IS '导入结果：SUCCESS';

